def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    tiles = []

    # Complete 2x2 squares.
    for r in range(h - 1):
        for c in range(w - 1):
            t = frozenset((r + dr, c + dc) for dr in range(2) for dc in range(2))
            if t <= cells:
                tiles.append((t, 1))

    # Three-cell L shapes, colored by their missing corner.
    # Missing TL, BL, TR, BR respectively.
    colors = {(0, 0): 2, (1, 0): 3, (0, 1): 4, (1, 1): 1}
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r + dr, c + dc) for dr in range(2) for dc in range(2)}
            for missing, color in colors.items():
                t = frozenset(box - {(r + missing[0], c + missing[1])})
                if t <= cells:
                    tiles.append((t, color))

    by_cell = {p: [] for p in cells}
    for t, color in tiles:
        for p in t:
            by_cell[p].append((t, color))

    def solve(remaining):
        if not remaining:
            return []
        p = min(remaining, key=lambda q: sum(t <= remaining for t, _ in by_cell[q]))
        options = [(t, color) for t, color in by_cell[p] if t <= remaining]
        options.sort(key=lambda x: -len(x[0]))
        for t, color in options:
            rest = solve(remaining - t)
            if rest is not None:
                return [(t, color)] + rest
        return None

    result = solve(cells)
    out = [[0] * w for _ in range(h)]
    if result is not None:
        for tile, color in result:
            for r, c in tile:
                out[r][c] = color
    return out
